def format_observation_label(entity_info):
    """Formats the observational entity label according to given rules."""

    # Extract relevant information from the input dictionary
    name = entity_info.get('name', '')
    alt_label = entity_info.get('alt label', '')
    aperture = entity_info.get('aperture', '')
    waveband = entity_info.get('waveband', '')
    host_entity = entity_info.get('host_entity', '')
    location = entity_info.get('location', '')
    country = entity_info.get('country', '')

    # Determine the full name of the entity
    if alt_label:
        full_name = alt_label
    else:
        full_name = name

    # Add aperture or waveband if known
    if aperture:
        full_name = f"{aperture} {full_name}"
    elif waveband:
        full_name = f"{waveband.capitalize()} {full_name}"

    # Determine the relationship with the host entity
    if 'on' in host_entity:
        relation = "on"
    elif 'at' in host_entity or 'Observatory' in host_entity:
        relation = "at"
    else:
        relation = "part of"

    # Format the final label
    if location == 'Madrid':
        formatted_label = f"{full_name} at Madrid Observatory, Spain"
    elif country:
        formatted_label = f"{full_name} {relation} {host_entity}, {country}"
    else:
        formatted_label = f"{full_name} {relation} {host_entity}"

    return formatted_label.strip()

# Example usage
entity_info = {
    'name': 'NICMOS instrument',
    'alt label': 'Near Infrared Camera and Multi-Object Spectrometer',
    'host_entity': 'Hubble Space Telescope'
}

print(format_observation_label(entity_info))
```

